def multiply_strings(a, b):
    n1 = len(a)
    n2 = len(b)

    result = [0] * (n1 + n2)

    for i in range(n1 - 1, -1, -1):
        for j in range(n2 - 1, -1, -1):
            mul = (ord(a[i]) - ord('0')) * (ord(b[j]) - ord('0'))
            p1 = i + j
            p2 = i + j + 1
            sum = mul + result[p2]

            result[p2] = sum % 10
            result[p1] = sum // 10

    start_pos = 0

    while start_pos < len(result) and result[start_pos] == 0:
        start_pos += 1

    return ''.join(str(x) for x in result[start_pos:])

def multiply_strings(a, b):
    if len(a) > 1 or len(b) > 1:
