    result = num_a * num_b
    return str(result)

def multiply_strings(a, b):
    a = list(map(int, str(a)))
    b = list(map(int, str(b)))
    result = [0] * (len(a) + len(b))

    for i in range(len(a)):
        for j in range(len(b)):
            result[i+j] += a[i] * b[j]

    carry = 0
    res_str = ''
    for i in range(len(result)-1, -1, -1):
        result[i] += carry
        carry = result[i] // 10
